/**
 * 将 Date 转化为指定格式的String.
 * 月(M)、日(d)、小时(h)、分(m)、秒(s)、季度(q) 可以用 1-2 个占位符，
 * 年(y)可以用 1-4 个占位符，毫秒(S)只能用 1 个占位符(是 1-3 位的数字)
 * 例子：
 * common.formatDate(new Date(), 'yyyy-MM-dd hh:mm:ss.S') ==> 2006-07-02 08:09:04.423
 * common.formatDate(new Date(), 'yyyy-M-d h:m:s.S')      ==> 2006-7-2 8:9:4.18
 * common.formatDate(new Date(), 'hh:mm:ss.S')            ==> 08:09:04.423
 *
 * @param date
 * @param fmt
 * @returns {*}
 */
exports.formatDate = function (date, fmt) { //author: meizz
    var o = {
        "M+": date.getMonth() + 1, //月份
        "d+": date.getDate(), //日
        "h+": date.getHours(), //小时
        "m+": date.getMinutes(), //分
        "s+": date.getSeconds(), //秒
        "q+": Math.floor((date.getMonth() + 3) / 3), //季度
        "S": date.getMilliseconds() //毫秒
    };
    if (/(y+)/.test(fmt)) fmt = fmt.replace(RegExp.$1, (date.getFullYear() + "").substr(4 - RegExp.$1.length));
    for (var k in o)
        if (new RegExp("(" + k + ")").test(fmt)) fmt = fmt.replace(RegExp.$1, (RegExp.$1.length == 1) ? (o[k]) : (("00" + o[k]).substr(("" + o[k]).length)));
    return fmt;
};


/**
 * Normalize a port into a number, string, or false.
 *
 * @param val
 * @returns {*}
 */
exports.normalizePort = function (val) {
    var port = parseInt(val, 10);

    if (isNaN(port)) {
        // named pipe
        return val;
    }

    if (port >= 0) {
        // port number
        return port;
    }

    return false;
};


/**
 * 对文本内容进行转义，通常用于防止发送到浏览器端的内容存在XSS攻击。
 *
 * @param str 要转义的原始字符串
 * @returns {string}
 */
exports.htmlEncode = function (str) {
    var s = str;

    if(str) {
        //s = str.replace(/&/g, "&amp;");
        s = s.replace(/</g, "&lt;");
        s = s.replace(/>/g, "&gt;");
        //s = s.replace(/ /g, "&nbsp;");
        //s = s.replace(/\'/g, "&#39;");
        //s = s.replace(/\"/g, "&quot;");
        //s = s.replace(/\n/g, "<br>");
    }

    return s;
};

/**
 * 在JS中返回当前系统的时间戳。
 *
 * @returns {number} 形如：1280977330748 的长整数
 */
exports.getCurrentUTCTimestamp = function () {
    return new Date().getTime();
};


